window.ALG0_ALGORITHMS = [{"id":"7e94e0d2-3ccb-4659-85cb-05e521e9f1b7","title":"Binary Search","category":"Searching","difficulty":"Easy","timeComplexity":"O(log n)","spaceComplexity":"O(1)","tags":"array, divide-and-conquer, sorted","pattern":"Binary Search","summary":"Finds a target in a sorted array by repeatedly halving the search interval.","notes":"The input must be sorted. Use left + (right - left) / 2 to avoid integer overflow.","code":"public static int BinarySearch(int[] nums, int target)\r\n{\r\n    int left = 0, right = nums.Length - 1;\r\n\r\n    while (left <= right)\r\n    {\r\n        int mid = left + (right - left) / 2;\r\n        if (nums[mid] == target) return mid;\r\n        if (nums[mid] < target) left = mid + 1;\r\n        else right = mid - 1;\r\n    }\r\n\r\n    return -1;\r\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9291354+02:00"},{"id":"ef8ac2f4-d9a3-4cbe-9769-d9e0a4a203d3","title":"Breadth-First Search","category":"Graphs","difficulty":"Medium","timeComplexity":"O(V + E)","spaceComplexity":"O(V)","tags":"graph, queue, shortest-path","pattern":"Graph Traversal","summary":"Explores a graph level by level and finds shortest paths in unweighted graphs.","notes":"Mark nodes visited when enqueuing them, not when dequeuing, to prevent duplicates.","code":"public static List<int> Bfs(List<int>[] graph, int start)\r\n{\r\n    var order = new List<int>();\r\n    var visited = new bool[graph.Length];\r\n    var queue = new Queue<int>();\r\n\r\n    visited[start] = true;\r\n    queue.Enqueue(start);\r\n\r\n    while (queue.Count > 0)\r\n    {\r\n        int node = queue.Dequeue();\r\n        order.Add(node);\r\n\r\n        foreach (int next in graph[node])\r\n            if (!visited[next])\r\n            {\r\n                visited[next] = true;\r\n                queue.Enqueue(next);\r\n            }\r\n    }\r\n\r\n    return order;\r\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9328122+02:00"},{"id":"04be400f-0221-4945-9bf0-3951c9da6bde","title":"Merge Sort","category":"Sorting","difficulty":"Medium","timeComplexity":"O(n log n)","spaceComplexity":"O(n)","tags":"array, stable, divide-and-conquer","pattern":"Divide and Conquer","summary":"Divides the array into halves, sorts each half, then merges the sorted results.","notes":"Stable and predictable, but requires auxiliary memory for merging.","code":"public static void MergeSort(int[] a, int left, int right)\r\n{\r\n    if (left >= right) return;\r\n    int mid = left + (right - left) / 2;\r\n    MergeSort(a, left, mid);\r\n    MergeSort(a, mid + 1, right);\r\n    Merge(a, left, mid, right);\r\n}\r\n\r\nprivate static void Merge(int[] a, int left, int mid, int right)\r\n{\r\n    int[] temp = new int[right - left + 1];\r\n    int i = left, j = mid + 1, k = 0;\r\n    while (i <= mid && j <= right)\r\n        temp[k++] = a[i] <= a[j] ? a[i++] : a[j++];\r\n    while (i <= mid) temp[k++] = a[i++];\r\n    while (j <= right) temp[k++] = a[j++];\r\n    Array.Copy(temp, 0, a, left, temp.Length);\r\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9329127+02:00"},{"id":"b020912f-a41e-4856-8c22-898f43e0e82f","title":"Dijkstra's Algorithm","category":"Graphs","difficulty":"Hard","timeComplexity":"O((V + E) log V)","spaceComplexity":"O(V + E)","tags":"graph, shortest-path, priority-queue","pattern":"Shortest Path","summary":"Computes shortest paths from one source in a graph with non-negative edge weights.","notes":"Do not use with negative-weight edges. Skip stale priority-queue entries.","code":"public static int[] Dijkstra(List<(int To, int Weight)>[] graph, int source)\r\n{\r\n    int[] distance = Enumerable.Repeat(int.MaxValue, graph.Length).ToArray();\r\n    var pq = new PriorityQueue<int, int>();\r\n    distance[source] = 0;\r\n    pq.Enqueue(source, 0);\r\n\r\n    while (pq.TryDequeue(out int node, out int cost))\r\n    {\r\n        if (cost != distance[node]) continue;\r\n        foreach (var (next, weight) in graph[node])\r\n        {\r\n            int candidate = cost + weight;\r\n            if (candidate >= distance[next]) continue;\r\n            distance[next] = candidate;\r\n            pq.Enqueue(next, candidate);\r\n        }\r\n    }\r\n    return distance;\r\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9329571+02:00"},{"id":"13f68929-69c5-4e1a-8bcc-6d01b701f005","title":"Longest Increasing Subsequence","category":"Dynamic Programming","difficulty":"Hard","timeComplexity":"O(n log n)","spaceComplexity":"O(n)","tags":"array, binary-search, patience-sorting","pattern":"Dynamic Programming + Binary Search","summary":"Finds the length of the longest strictly increasing subsequence using a tails array.","notes":"tails[i] stores the smallest possible tail for an increasing subsequence of length i + 1.","code":"public static int LengthOfLis(int[] nums)\r\n{\r\n    var tails = new List<int>();\r\n    foreach (int value in nums)\r\n    {\r\n        int index = tails.BinarySearch(value);\r\n        if (index < 0) index = ~index;\r\n        if (index == tails.Count) tails.Add(value);\r\n        else tails[index] = value;\r\n    }\r\n    return tails.Count;\r\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9330013+02:00"},{"id":"1aec6921-59d5-45d7-8510-1e9d16a18f47","title":"Two Sum","category":"Arrays","difficulty":"Easy","timeComplexity":"O(n)","spaceComplexity":"O(n)","tags":"array, hash-map, interview","pattern":"Hash Map Lookup","summary":"Returns indices of two values whose sum equals the requested target.","notes":"Check the complement before inserting the current number so one element is never reused.","code":"public static int[] TwoSum(int[] nums, int target)\r\n{\r\n    var seen = new Dictionary<int, int>();\r\n    for (int i = 0; i < nums.Length; i++)\r\n    {\r\n        int complement = target - nums[i];\r\n        if (seen.TryGetValue(complement, out int j))\r\n            return [j, i];\r\n        seen[nums[i]] = i;\r\n    }\r\n    return [];\r\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9330391+02:00"},{"id":"90c54b19-a4c2-4bb5-a7f8-0f26d479e4f3","title":"Lower Bound","category":"Searching","difficulty":"Medium","timeComplexity":"O(log n)","spaceComplexity":"O(1)","tags":"array, sorted, boundary","pattern":"Binary Search","summary":"Finds the first index whose value is greater than or equal to the target.","notes":"Use a half-open interval [left, right). The answer may equal nums.Length.","code":"public static int LowerBound(int[] nums, int target)\n{\n    int left = 0, right = nums.Length;\n    while (left < right)\n    {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] < target) left = mid + 1;\n        else right = mid;\n    }\n    return left;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9330826+02:00"},{"id":"9e88aabb-132c-4416-8ce4-88a76f0d0c8d","title":"Kadane's Algorithm","category":"Arrays","difficulty":"Medium","timeComplexity":"O(n)","spaceComplexity":"O(1)","tags":"array, maximum-subarray, greedy","pattern":"Dynamic Programming","summary":"Finds the maximum sum over all non-empty contiguous subarrays.","notes":"Initialize from the first value so arrays containing only negative values work correctly.","code":"public static int MaxSubarraySum(int[] nums)\n{\n    if (nums.Length == 0) throw new ArgumentException(\"Array cannot be empty.\");\n    int endingHere = nums[0], best = nums[0];\n    for (int i = 1; i < nums.Length; i++)\n    {\n        endingHere = Math.Max(nums[i], endingHere + nums[i]);\n        best = Math.Max(best, endingHere);\n    }\n    return best;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9331441+02:00"},{"id":"296cc80e-1aa5-4f39-ae9c-522353f0e67f","title":"Prefix Sum Range Query","category":"Arrays","difficulty":"Easy","timeComplexity":"O(n) build, O(1) query","spaceComplexity":"O(n)","tags":"array, prefix-sum, range-query","pattern":"Prefix Sum","summary":"Precomputes cumulative sums so any inclusive range sum can be answered in constant time.","notes":"Store n + 1 values so prefix[0] represents the empty prefix and avoids special cases.","code":"public sealed class RangeSum\n{\n    private readonly long[] _prefix;\n\n    public RangeSum(int[] nums)\n    {\n        _prefix = new long[nums.Length + 1];\n        for (int i = 0; i < nums.Length; i++)\n            _prefix[i + 1] = _prefix[i] + nums[i];\n    }\n\n    public long Query(int left, int right) =>\n        _prefix[right + 1] - _prefix[left];\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9331855+02:00"},{"id":"e3227526-d14c-485d-845f-c95347bc0fef","title":"Sliding Window Maximum","category":"Arrays","difficulty":"Hard","timeComplexity":"O(n)","spaceComplexity":"O(k)","tags":"array, sliding-window, deque, monotonic","pattern":"Monotonic Deque","summary":"Returns the maximum value in every fixed-size window using a decreasing deque of indices.","notes":"Remove expired indices from the front and weaker values from the back.","code":"public static int[] MaxSlidingWindow(int[] nums, int k)\n{\n    if (k <= 0 || k > nums.Length) return [];\n    var deque = new LinkedList<int>();\n    var result = new int[nums.Length - k + 1];\n\n    for (int i = 0; i < nums.Length; i++)\n    {\n        if (deque.First is not null && deque.First.Value <= i - k)\n            deque.RemoveFirst();\n        while (deque.Last is not null && nums[deque.Last.Value] <= nums[i])\n            deque.RemoveLast();\n        deque.AddLast(i);\n        if (i >= k - 1) result[i - k + 1] = nums[deque.First!.Value];\n    }\n    return result;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9332218+02:00"},{"id":"5143745e-15ae-404b-9393-e996b3597486","title":"Quick Sort","category":"Sorting","difficulty":"Medium","timeComplexity":"O(n log n) average","spaceComplexity":"O(log n) average","tags":"array, in-place, divide-and-conquer","pattern":"Partitioning","summary":"Sorts in place by partitioning values around a pivot, then recursively sorting both sides.","notes":"Worst-case time is O(n²). Randomizing the pivot or shuffling reduces adversarial behavior.","code":"public static void QuickSort(int[] nums, int left, int right)\n{\n    while (left < right)\n    {\n        int i = left, j = right;\n        int pivot = nums[left + (right - left) / 2];\n        while (i <= j)\n        {\n            while (nums[i] < pivot) i++;\n            while (nums[j] > pivot) j--;\n            if (i <= j) (nums[i++], nums[j--]) = (nums[j], nums[i]);\n        }\n        if (j - left < right - i)\n        {\n            if (left < j) QuickSort(nums, left, j);\n            left = i;\n        }\n        else\n        {\n            if (i < right) QuickSort(nums, i, right);\n            right = j;\n        }\n    }\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9332592+02:00"},{"id":"32be03e2-040a-4923-b0d2-4e9742793930","title":"Depth-First Search","category":"Graphs","difficulty":"Easy","timeComplexity":"O(V + E)","spaceComplexity":"O(V)","tags":"graph, stack, traversal, components","pattern":"Graph Traversal","summary":"Explores as far as possible along each branch using an explicit stack.","notes":"Push neighbors in reverse order when deterministic adjacency-list order matters.","code":"public static List<int> Dfs(List<int>[] graph, int start)\n{\n    var order = new List<int>();\n    var visited = new bool[graph.Length];\n    var stack = new Stack<int>();\n    stack.Push(start);\n\n    while (stack.Count > 0)\n    {\n        int node = stack.Pop();\n        if (visited[node]) continue;\n        visited[node] = true;\n        order.Add(node);\n        for (int i = graph[node].Count - 1; i >= 0; i--)\n            if (!visited[graph[node][i]]) stack.Push(graph[node][i]);\n    }\n    return order;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9333227+02:00"},{"id":"75711eec-7bdd-4d2b-8113-7c7bc4909c80","title":"Topological Sort (Kahn)","category":"Graphs","difficulty":"Medium","timeComplexity":"O(V + E)","spaceComplexity":"O(V)","tags":"graph, dag, indegree, queue","pattern":"Topological Sort","summary":"Orders a directed acyclic graph so every dependency appears before its dependents.","notes":"If fewer than V nodes are produced, the graph contains a directed cycle.","code":"public static int[] TopologicalSort(List<int>[] graph)\n{\n    int[] indegree = new int[graph.Length];\n    foreach (var edges in graph)\n        foreach (int next in edges) indegree[next]++;\n\n    var queue = new Queue<int>(Enumerable.Range(0, graph.Length)\n        .Where(node => indegree[node] == 0));\n    var order = new List<int>();\n    while (queue.Count > 0)\n    {\n        int node = queue.Dequeue();\n        order.Add(node);\n        foreach (int next in graph[node])\n            if (--indegree[next] == 0) queue.Enqueue(next);\n    }\n    return order.Count == graph.Length ? order.ToArray() : [];\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9333685+02:00"},{"id":"7eb52fd4-175b-4911-a1df-6f4fee9a6a67","title":"Disjoint Set Union","category":"Graphs","difficulty":"Medium","timeComplexity":"O(α(n)) amortized","spaceComplexity":"O(n)","tags":"graph, union-find, connectivity, mst","pattern":"Union-Find","summary":"Tracks connected components efficiently with path compression and union by size.","notes":"Useful for Kruskal's MST, dynamic connectivity, and cycle detection in undirected graphs.","code":"public sealed class DisjointSet\n{\n    private readonly int[] _parent;\n    private readonly int[] _size;\n\n    public DisjointSet(int n)\n    {\n        _parent = Enumerable.Range(0, n).ToArray();\n        _size = Enumerable.Repeat(1, n).ToArray();\n    }\n\n    public int Find(int x) => _parent[x] == x\n        ? x\n        : _parent[x] = Find(_parent[x]);\n\n    public bool Union(int a, int b)\n    {\n        a = Find(a); b = Find(b);\n        if (a == b) return false;\n        if (_size[a] < _size[b]) (a, b) = (b, a);\n        _parent[b] = a;\n        _size[a] += _size[b];\n        return true;\n    }\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9334019+02:00"},{"id":"dd682898-0828-4944-bb19-c869aaf351da","title":"Kruskal's Minimum Spanning Tree","category":"Graphs","difficulty":"Hard","timeComplexity":"O(E log E)","spaceComplexity":"O(V + E)","tags":"graph, mst, greedy, union-find","pattern":"Greedy + Union-Find","summary":"Builds a minimum spanning forest by taking the lightest edge that connects two components.","notes":"For a connected graph, exactly V - 1 edges must be accepted.","code":"public static long Kruskal(int vertices, List<(int U, int V, int W)> edges)\n{\n    var dsu = new DisjointSet(vertices);\n    long cost = 0;\n    int used = 0;\n    foreach (var (u, v, weight) in edges.OrderBy(e => e.W))\n    {\n        if (!dsu.Union(u, v)) continue;\n        cost += weight;\n        if (++used == vertices - 1) break;\n    }\n    if (used != vertices - 1) throw new InvalidOperationException(\"Graph is disconnected.\");\n    return cost;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9334381+02:00"},{"id":"f33e88cf-7e1b-40ae-9fc8-16e2ffe29cab","title":"Binary Tree Level Order","category":"Trees","difficulty":"Medium","timeComplexity":"O(n)","spaceComplexity":"O(w)","tags":"tree, bfs, queue, levels","pattern":"Breadth-First Search","summary":"Traverses a binary tree one depth level at a time.","notes":"Capture the queue count before each level; it is the exact number of nodes in that level.","code":"public static List<List<int>> LevelOrder(TreeNode? root)\n{\n    var result = new List<List<int>>();\n    if (root is null) return result;\n    var queue = new Queue<TreeNode>();\n    queue.Enqueue(root);\n\n    while (queue.Count > 0)\n    {\n        int levelSize = queue.Count;\n        var level = new List<int>(levelSize);\n        while (levelSize-- > 0)\n        {\n            var node = queue.Dequeue();\n            level.Add(node.Value);\n            if (node.Left is not null) queue.Enqueue(node.Left);\n            if (node.Right is not null) queue.Enqueue(node.Right);\n        }\n        result.Add(level);\n    }\n    return result;\n}\n\npublic sealed record TreeNode(int Value, TreeNode? Left = null, TreeNode? Right = null);","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9334763+02:00"},{"id":"a46e812e-bf44-40da-af58-90b8f18afc67","title":"Lowest Common Ancestor","category":"Trees","difficulty":"Medium","timeComplexity":"O(n)","spaceComplexity":"O(h)","tags":"tree, recursion, lca","pattern":"Tree Recursion","summary":"Finds the lowest node that has both targets in its subtree in a general binary tree.","notes":"This version assumes both targets exist. For uncertain inputs, also propagate how many targets were found.","code":"public static TreeNode? LowestCommonAncestor(TreeNode? root, TreeNode p, TreeNode q)\n{\n    if (root is null || ReferenceEquals(root, p) || ReferenceEquals(root, q))\n        return root;\n\n    var left = LowestCommonAncestor(root.Left, p, q);\n    var right = LowestCommonAncestor(root.Right, p, q);\n    if (left is not null && right is not null) return root;\n    return left ?? right;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9335126+02:00"},{"id":"8ae006b6-c28e-403a-9980-f5e871f67878","title":"KMP String Search","category":"Strings","difficulty":"Hard","timeComplexity":"O(n + m)","spaceComplexity":"O(m)","tags":"string, pattern-matching, prefix-table","pattern":"Prefix Function","summary":"Finds the first pattern occurrence without rechecking text characters after a mismatch.","notes":"The LPS table stores the longest proper prefix that is also a suffix for each pattern prefix.","code":"public static int KmpIndexOf(string text, string pattern)\n{\n    if (pattern.Length == 0) return 0;\n    int[] lps = new int[pattern.Length];\n    for (int i = 1, length = 0; i < pattern.Length;)\n        if (pattern[i] == pattern[length]) lps[i++] = ++length;\n        else if (length > 0) length = lps[length - 1];\n        else lps[i++] = 0;\n\n    for (int i = 0, j = 0; i < text.Length;)\n    {\n        if (text[i] == pattern[j]) { i++; j++; }\n        if (j == pattern.Length) return i - j;\n        if (i < text.Length && text[i] != pattern[j])\n            if (j > 0) j = lps[j - 1]; else i++;\n    }\n    return -1;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9335451+02:00"},{"id":"85ba1daf-5bf8-4384-b8c9-19a510fd97fb","title":"Trie (Prefix Tree)","category":"Strings","difficulty":"Medium","timeComplexity":"O(L) per operation","spaceComplexity":"O(total characters)","tags":"string, prefix, dictionary, autocomplete","pattern":"Trie","summary":"Stores strings by shared prefixes for fast insert, exact lookup, and prefix lookup.","notes":"A dictionary-based node handles arbitrary characters; an array of 26 children is faster for lowercase English letters.","code":"public sealed class Trie\n{\n    private sealed class Node\n    {\n        public Dictionary<char, Node> Children { get; } = [];\n        public bool IsWord { get; set; }\n    }\n\n    private readonly Node _root = new();\n\n    public void Insert(string word)\n    {\n        var node = _root;\n        foreach (char c in word)\n        {\n            if (!node.Children.TryGetValue(c, out var next))\n                node.Children[c] = next = new Node();\n            node = next;\n        }\n        node.IsWord = true;\n    }\n\n    public bool Contains(string word) => Find(word)?.IsWord == true;\n    public bool StartsWith(string prefix) => Find(prefix) is not null;\n\n    private Node? Find(string text)\n    {\n        var node = _root;\n        foreach (char c in text)\n            if (!node.Children.TryGetValue(c, out node)) return null;\n        return node;\n    }\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9335795+02:00"},{"id":"b266fda1-dafd-4289-b421-b934112184c4","title":"Coin Change","category":"Dynamic Programming","difficulty":"Medium","timeComplexity":"O(amount × coins)","spaceComplexity":"O(amount)","tags":"dp, minimum, unbounded-knapsack","pattern":"Unbounded Knapsack","summary":"Computes the minimum number of reusable coins needed to reach an exact amount.","notes":"Use amount + 1 as an unreachable sentinel because a valid answer can never need more than amount coins.","code":"public static int CoinChange(int[] coins, int amount)\n{\n    int[] dp = Enumerable.Repeat(amount + 1, amount + 1).ToArray();\n    dp[0] = 0;\n    for (int value = 1; value <= amount; value++)\n        foreach (int coin in coins)\n            if (coin <= value) dp[value] = Math.Min(dp[value], dp[value - coin] + 1);\n    return dp[amount] > amount ? -1 : dp[amount];\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9336207+02:00"},{"id":"83bf2c20-e42a-4317-ae7d-0198f105c659","title":"0/1 Knapsack","category":"Dynamic Programming","difficulty":"Medium","timeComplexity":"O(n × capacity)","spaceComplexity":"O(capacity)","tags":"dp, optimization, capacity","pattern":"0/1 Knapsack","summary":"Maximizes value when each item can be selected at most once under a capacity limit.","notes":"Iterate capacity backward; forward iteration would allow the same item to be reused.","code":"public static int Knapsack(int[] weights, int[] values, int capacity)\n{\n    int[] dp = new int[capacity + 1];\n    for (int i = 0; i < weights.Length; i++)\n        for (int current = capacity; current >= weights[i]; current--)\n            dp[current] = Math.Max(dp[current], dp[current - weights[i]] + values[i]);\n    return dp[capacity];\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9336586+02:00"},{"id":"51e37453-1982-4acc-a48b-b59e64f285df","title":"Generate Permutations","category":"Backtracking","difficulty":"Medium","timeComplexity":"O(n · n!)","spaceComplexity":"O(n)","tags":"backtracking, permutation, recursion","pattern":"Backtracking","summary":"Generates every ordering by choosing a value for each position and undoing the choice afterward.","notes":"For duplicate input values, sort first and skip equal unused values at the same recursion depth.","code":"public static List<int[]> Permutations(int[] nums)\n{\n    var result = new List<int[]>();\n    void Search(int index)\n    {\n        if (index == nums.Length) { result.Add((int[])nums.Clone()); return; }\n        for (int i = index; i < nums.Length; i++)\n        {\n            (nums[index], nums[i]) = (nums[i], nums[index]);\n            Search(index + 1);\n            (nums[index], nums[i]) = (nums[i], nums[index]);\n        }\n    }\n    Search(0);\n    return result;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9336922+02:00"},{"id":"20a7e794-330b-443a-9f20-c6de14052ec0","title":"Next Greater Element","category":"Stacks & Queues","difficulty":"Medium","timeComplexity":"O(n)","spaceComplexity":"O(n)","tags":"stack, monotonic, array","pattern":"Monotonic Stack","summary":"Finds the next larger value to the right of every array element.","notes":"Store indices rather than values when the result must align with original positions.","code":"public static int[] NextGreater(int[] nums)\n{\n    int[] answer = Enumerable.Repeat(-1, nums.Length).ToArray();\n    var stack = new Stack<int>();\n    for (int i = 0; i < nums.Length; i++)\n    {\n        while (stack.Count > 0 && nums[stack.Peek()] < nums[i])\n            answer[stack.Pop()] = nums[i];\n        stack.Push(i);\n    }\n    return answer;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9337234+02:00"},{"id":"caad0a3c-9c01-4b30-991e-cca36a37759c","title":"Top K Frequent Elements","category":"Arrays","difficulty":"Medium","timeComplexity":"O(n log k)","spaceComplexity":"O(n)","tags":"hash-map, heap, top-k","pattern":"Heap / Frequency Map","summary":"Returns the k most frequent values using a frequency map and a bounded min-heap.","notes":"Keeping only k heap entries is preferable when k is much smaller than the number of distinct values.","code":"public static int[] TopKFrequent(int[] nums, int k)\n{\n    var counts = nums.GroupBy(x => x).ToDictionary(g => g.Key, g => g.Count());\n    var heap = new PriorityQueue<int, int>();\n    foreach (var (value, frequency) in counts)\n    {\n        heap.Enqueue(value, frequency);\n        if (heap.Count > k) heap.Dequeue();\n    }\n    var answer = new int[Math.Min(k, heap.Count)];\n    for (int i = answer.Length - 1; i >= 0; i--)\n        answer[i] = heap.Dequeue();\n    return answer;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9337582+02:00"},{"id":"c9755fde-7201-4856-94fa-ef7b7e89688b","title":"Detect Directed Cycle","category":"Graphs","difficulty":"Medium","timeComplexity":"O(V + E)","spaceComplexity":"O(V)","tags":"graph, cycle, dfs, coloring","pattern":"DFS Coloring","summary":"Detects a cycle in a directed graph using unvisited, visiting, and finished states.","notes":"An edge to a visiting node is a back edge and proves that a directed cycle exists.","code":"public static bool HasDirectedCycle(List<int>[] graph)\n{\n    var state = new byte[graph.Length];\n    bool Visit(int node)\n    {\n        if (state[node] == 1) return true;\n        if (state[node] == 2) return false;\n        state[node] = 1;\n        foreach (int next in graph[node])\n            if (Visit(next)) return true;\n        state[node] = 2;\n        return false;\n    }\n    return Enumerable.Range(0, graph.Length).Any(node => state[node] == 0 && Visit(node));\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9337916+02:00"},{"id":"d93c13c1-959a-4222-8651-c563227c3cd0","title":"Bubble Sort","category":"Sorting","difficulty":"Easy","timeComplexity":"O(n²)","spaceComplexity":"O(1)","tags":"sorting, in-place, stable","pattern":"Exchange Sort","summary":"Repeatedly swaps adjacent out-of-order values; useful for learning, rarely for production.","notes":"The swapped flag makes already-sorted input finish in O(n).","code":"public static void BubbleSort(int[] nums)\n{\n    for (int end = nums.Length - 1; end > 0; end--)\n    {\n        bool swapped = false;\n        for (int i = 0; i < end; i++)\n            if (nums[i] > nums[i + 1])\n            {\n                (nums[i], nums[i + 1]) = (nums[i + 1], nums[i]);\n                swapped = true;\n            }\n        if (!swapped) return;\n    }\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9338327+02:00"},{"id":"18d932ee-8479-468e-9cbc-249be92de1f2","title":"Selection Sort","category":"Sorting","difficulty":"Easy","timeComplexity":"O(n²)","spaceComplexity":"O(1)","tags":"sorting, in-place, comparison","pattern":"Selection","summary":"Selects the smallest remaining value and places it at the next sorted position.","notes":"It performs only O(n) swaps but is not stable in its usual form.","code":"public static void SelectionSort(int[] nums)\n{\n    for (int i = 0; i < nums.Length - 1; i++)\n    {\n        int minIndex = i;\n        for (int j = i + 1; j < nums.Length; j++)\n            if (nums[j] < nums[minIndex]) minIndex = j;\n        if (minIndex != i) (nums[i], nums[minIndex]) = (nums[minIndex], nums[i]);\n    }\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9338661+02:00"},{"id":"0c7e6ab1-f542-453f-8e62-60897c4d74b2","title":"Insertion Sort","category":"Sorting","difficulty":"Easy","timeComplexity":"O(n²), O(n) nearly sorted","spaceComplexity":"O(1)","tags":"sorting, stable, in-place","pattern":"Incremental Insertion","summary":"Builds a sorted prefix by inserting each new value into its correct position.","notes":"Excellent for small or nearly sorted inputs and commonly used inside hybrid sorts.","code":"public static void InsertionSort(int[] nums)\n{\n    for (int i = 1; i < nums.Length; i++)\n    {\n        int value = nums[i], j = i - 1;\n        while (j >= 0 && nums[j] > value)\n        {\n            nums[j + 1] = nums[j];\n            j--;\n        }\n        nums[j + 1] = value;\n    }\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9339010+02:00"},{"id":"57c15656-1ce6-4cec-a127-8abec4ead35c","title":"Heap Sort","category":"Sorting","difficulty":"Medium","timeComplexity":"O(n log n)","spaceComplexity":"O(1)","tags":"sorting, heap, in-place","pattern":"Heap","summary":"Builds a max heap and repeatedly moves its largest value to the sorted suffix.","notes":"Predictable O(n log n) and constant extra space, but not stable.","code":"public static void HeapSort(int[] nums)\n{\n    for (int i = nums.Length / 2 - 1; i >= 0; i--) SiftDown(nums, i, nums.Length);\n    for (int end = nums.Length - 1; end > 0; end--)\n    {\n        (nums[0], nums[end]) = (nums[end], nums[0]);\n        SiftDown(nums, 0, end);\n    }\n}\n\nprivate static void SiftDown(int[] a, int root, int length)\n{\n    while (root * 2 + 1 < length)\n    {\n        int child = root * 2 + 1;\n        if (child + 1 < length && a[child + 1] > a[child]) child++;\n        if (a[root] >= a[child]) return;\n        (a[root], a[child]) = (a[child], a[root]);\n        root = child;\n    }\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9339327+02:00"},{"id":"e5bcf315-f4dd-48b8-ae37-e60c02a092c4","title":"Counting Sort","category":"Sorting","difficulty":"Medium","timeComplexity":"O(n + k)","spaceComplexity":"O(k)","tags":"sorting, integer, non-comparison","pattern":"Frequency Counting","summary":"Sorts bounded integers by counting how often every value occurs.","notes":"Avoid it when max - min is enormous compared with the input length.","code":"public static int[] CountingSort(int[] nums)\n{\n    if (nums.Length == 0) return [];\n    int min = nums.Min(), max = nums.Max();\n    int[] counts = new int[max - min + 1];\n    foreach (int value in nums) counts[value - min]++;\n    var result = new int[nums.Length];\n    for (int value = 0, index = 0; value < counts.Length; value++)\n        while (counts[value]-- > 0) result[index++] = value + min;\n    return result;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9339688+02:00"},{"id":"9a13cf85-8aec-45e3-bddc-52353942671f","title":"Radix Sort","category":"Sorting","difficulty":"Medium","timeComplexity":"O(d · (n + 10))","spaceComplexity":"O(n + 10)","tags":"sorting, integer, stable","pattern":"Digit Bucketing","summary":"Stably sorts non-negative integers one decimal digit at a time.","notes":"This version accepts non-negative integers; handle signs separately when negatives are allowed.","code":"public static void RadixSort(int[] nums)\n{\n    if (nums.Any(x => x < 0)) throw new ArgumentException(\"Non-negative values only.\");\n    if (nums.Length == 0) return;\n    int[] output = new int[nums.Length];\n    for (long place = 1; nums.Max() / place > 0; place *= 10)\n    {\n        int[] count = new int[10];\n        foreach (int value in nums) count[(int)(value / place % 10)]++;\n        for (int i = 1; i < 10; i++) count[i] += count[i - 1];\n        for (int i = nums.Length - 1; i >= 0; i--)\n            output[--count[(int)(nums[i] / place % 10)]] = nums[i];\n        Array.Copy(output, nums, nums.Length);\n    }\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9340028+02:00"},{"id":"b105a1fc-5869-4ac4-bbea-d43ecd165088","title":"Valid Parentheses","category":"Stacks & Queues","difficulty":"Easy","timeComplexity":"O(n)","spaceComplexity":"O(n)","tags":"stack, string, brackets","pattern":"Stack Matching","summary":"Checks whether every closing bracket matches the most recent unmatched opening bracket.","notes":"Reject immediately when a closing bracket appears with an empty stack.","code":"public static bool IsValidParentheses(string text)\n{\n    var stack = new Stack<char>();\n    foreach (char c in text)\n    {\n        if (c is '(' or '[' or '{') stack.Push(c);\n        else if (c is ')' or ']' or '}')\n        {\n            if (stack.Count == 0) return false;\n            char open = stack.Pop();\n            if ((open, c) is not ('(', ')') and not ('[', ']') and not ('{', '}')) return false;\n        }\n    }\n    return stack.Count == 0;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9341010+02:00"},{"id":"932c7c65-28b3-46a5-ab2b-4782f6b8cf52","title":"Valid Anagram","category":"Strings","difficulty":"Easy","timeComplexity":"O(n)","spaceComplexity":"O(1) alphabet","tags":"string, frequency, hash-map","pattern":"Frequency Counting","summary":"Determines whether two strings contain exactly the same characters with the same counts.","notes":"Use a dictionary for arbitrary Unicode; this compact version assumes lowercase English letters.","code":"public static bool IsAnagram(string first, string second)\n{\n    if (first.Length != second.Length) return false;\n    int[] counts = new int[26];\n    for (int i = 0; i < first.Length; i++)\n    {\n        counts[first[i] - 'a']++;\n        counts[second[i] - 'a']--;\n    }\n    return counts.All(count => count == 0);\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9341527+02:00"},{"id":"0e175b00-d0e3-4112-9762-c2c0495837b3","title":"Group Anagrams","category":"Strings","difficulty":"Medium","timeComplexity":"O(n · k log k)","spaceComplexity":"O(n · k)","tags":"string, hash-map, grouping","pattern":"Canonical Key","summary":"Groups words that share the same sorted-character signature.","notes":"A 26-count signature improves this to O(n · k) for lowercase English input.","code":"public static IList<IList<string>> GroupAnagrams(string[] words)\n{\n    var groups = new Dictionary<string, IList<string>>();\n    foreach (string word in words)\n    {\n        string key = new string(word.OrderBy(c => c).ToArray());\n        if (!groups.TryGetValue(key, out var group))\n            groups[key] = group = new List<string>();\n        group.Add(word);\n    }\n    return groups.Values.ToList();\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9341931+02:00"},{"id":"0d81233b-b61b-4b69-8f9a-1f15cfcb1677","title":"Longest Substring Without Repeating","category":"Strings","difficulty":"Medium","timeComplexity":"O(n)","spaceComplexity":"O(min(n, alphabet))","tags":"string, sliding-window, hash-map","pattern":"Sliding Window","summary":"Finds the longest substring containing no repeated character.","notes":"Move the left boundary forward only; never move it backward after finding an older duplicate.","code":"public static int LongestUniqueSubstring(string text)\n{\n    var lastSeen = new Dictionary<char, int>();\n    int left = 0, best = 0;\n    for (int right = 0; right < text.Length; right++)\n    {\n        if (lastSeen.TryGetValue(text[right], out int previous))\n            left = Math.Max(left, previous + 1);\n        lastSeen[text[right]] = right;\n        best = Math.Max(best, right - left + 1);\n    }\n    return best;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9342319+02:00"},{"id":"cf1687fb-4142-4741-964d-277719cfe09b","title":"Valid Palindrome","category":"Strings","difficulty":"Easy","timeComplexity":"O(n)","spaceComplexity":"O(1)","tags":"string, two-pointers, palindrome","pattern":"Two Pointers","summary":"Checks whether the alphanumeric characters read the same forward and backward.","notes":"Skip punctuation on both sides before comparing case-insensitively.","code":"public static bool IsPalindrome(string text)\n{\n    int left = 0, right = text.Length - 1;\n    while (left < right)\n    {\n        while (left < right && !char.IsLetterOrDigit(text[left])) left++;\n        while (left < right && !char.IsLetterOrDigit(text[right])) right--;\n        if (char.ToLowerInvariant(text[left++]) != char.ToLowerInvariant(text[right--])) return false;\n    }\n    return true;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9342706+02:00"},{"id":"bdc6b799-50bf-4f05-bca3-5502a62b05cd","title":"Reverse Linked List","category":"Linked Lists","difficulty":"Easy","timeComplexity":"O(n)","spaceComplexity":"O(1)","tags":"linked-list, pointers, iterative","pattern":"Pointer Reversal","summary":"Reverses a singly linked list by redirecting each node's next pointer.","notes":"Save next before overwriting the pointer or the rest of the list becomes unreachable.","code":"public static ListNode? ReverseList(ListNode? head)\n{\n    ListNode? previous = null;\n    while (head is not null)\n    {\n        ListNode? next = head.Next;\n        head.Next = previous;\n        previous = head;\n        head = next;\n    }\n    return previous;\n}\n\npublic sealed class ListNode(int value, ListNode? next = null)\n{\n    public int Value { get; set; } = value;\n    public ListNode? Next { get; set; } = next;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9343063+02:00"},{"id":"2d98b587-094b-452d-8114-9f4e2bf892d1","title":"Linked List Cycle","category":"Linked Lists","difficulty":"Easy","timeComplexity":"O(n)","spaceComplexity":"O(1)","tags":"linked-list, cycle, two-pointers","pattern":"Fast & Slow Pointers","summary":"Detects a cycle by moving one pointer once and another pointer twice per step.","notes":"If a cycle exists, the two pointers must eventually meet inside it.","code":"public static bool HasCycle(ListNode? head)\n{\n    ListNode? slow = head, fast = head;\n    while (fast?.Next is not null)\n    {\n        slow = slow!.Next;\n        fast = fast.Next.Next;\n        if (ReferenceEquals(slow, fast)) return true;\n    }\n    return false;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9343396+02:00"},{"id":"c059733e-0f03-4ef7-800a-43787b5ecdd4","title":"Merge Two Sorted Lists","category":"Linked Lists","difficulty":"Easy","timeComplexity":"O(n + m)","spaceComplexity":"O(1)","tags":"linked-list, merge, sentinel","pattern":"Two Pointers","summary":"Merges two sorted linked lists by repeatedly attaching the smaller current node.","notes":"A dummy head removes special cases for initializing the result list.","code":"public static ListNode? MergeLists(ListNode? first, ListNode? second)\n{\n    var dummy = new ListNode(0);\n    var tail = dummy;\n    while (first is not null && second is not null)\n    {\n        if (first.Value <= second.Value) { tail.Next = first; first = first.Next; }\n        else { tail.Next = second; second = second.Next; }\n        tail = tail.Next;\n    }\n    tail.Next = first ?? second;\n    return dummy.Next;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9343766+02:00"},{"id":"59393f57-18ad-434b-9020-962d3353cdc1","title":"Remove Nth Node From End","category":"Linked Lists","difficulty":"Medium","timeComplexity":"O(n)","spaceComplexity":"O(1)","tags":"linked-list, two-pointers, sentinel","pattern":"Two Pointers + Sentinel","summary":"Removes the nth node from the end in one pass by keeping two pointers n nodes apart.","notes":"Using a dummy node cleanly handles removing the original head.","code":"public static ListNode? RemoveNthFromEnd(ListNode? head, int n)\n{\n    var dummy = new ListNode(0, head);\n    ListNode fast = dummy, slow = dummy;\n    for (int i = 0; i < n; i++) fast = fast.Next ?? throw new ArgumentOutOfRangeException(nameof(n));\n    while (fast.Next is not null) { fast = fast.Next; slow = slow.Next!; }\n    slow.Next = slow.Next?.Next;\n    return dummy.Next;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9344132+02:00"},{"id":"23cf2074-94c2-413d-88c2-a9f8f004cfae","title":"Merge Intervals","category":"Arrays","difficulty":"Medium","timeComplexity":"O(n log n)","spaceComplexity":"O(n)","tags":"array, intervals, sorting","pattern":"Sort + Sweep","summary":"Combines every pair of overlapping intervals after sorting by start position.","notes":"Touching intervals merge when next.Start <= current.End; adjust this rule for open intervals.","code":"public static int[][] MergeIntervals(int[][] intervals)\n{\n    if (intervals.Length == 0) return [];\n    Array.Sort(intervals, (a, b) => a[0].CompareTo(b[0]));\n    var result = new List<int[]> { (int[])intervals[0].Clone() };\n    foreach (var interval in intervals.Skip(1))\n    {\n        int[] last = result[^1];\n        if (interval[0] <= last[1]) last[1] = Math.Max(last[1], interval[1]);\n        else result.Add((int[])interval.Clone());\n    }\n    return result.ToArray();\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9344467+02:00"},{"id":"95b8dc55-f95c-4eb2-8d77-d4de061f27ce","title":"Three Sum","category":"Arrays","difficulty":"Medium","timeComplexity":"O(n²)","spaceComplexity":"O(1) excluding output","tags":"array, two-pointers, sorting","pattern":"Sort + Two Pointers","summary":"Finds unique triples whose values sum to zero by fixing one value and scanning the rest with two pointers.","notes":"Skip equal fixed values and equal pointer values after finding a triple to avoid duplicates.","code":"public static IList<IList<int>> ThreeSum(int[] nums)\n{\n    Array.Sort(nums);\n    var result = new List<IList<int>>();\n    for (int i = 0; i < nums.Length - 2; i++)\n    {\n        if (i > 0 && nums[i] == nums[i - 1]) continue;\n        int left = i + 1, right = nums.Length - 1;\n        while (left < right)\n        {\n            long sum = (long)nums[i] + nums[left] + nums[right];\n            if (sum < 0) left++;\n            else if (sum > 0) right--;\n            else\n            {\n                result.Add([nums[i], nums[left], nums[right]]);\n                int a = nums[left], b = nums[right];\n                while (left < right && nums[left] == a) left++;\n                while (left < right && nums[right] == b) right--;\n            }\n        }\n    }\n    return result;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9344852+02:00"},{"id":"f0173250-c206-48fd-b7d3-8987bc11f116","title":"Container With Most Water","category":"Arrays","difficulty":"Medium","timeComplexity":"O(n)","spaceComplexity":"O(1)","tags":"array, two-pointers, greedy","pattern":"Two Pointers","summary":"Maximizes contained area by moving inward from the widest pair of vertical lines.","notes":"Move the shorter line because keeping it cannot improve height while width decreases.","code":"public static int MaxArea(int[] heights)\n{\n    int left = 0, right = heights.Length - 1, best = 0;\n    while (left < right)\n    {\n        best = Math.Max(best, Math.Min(heights[left], heights[right]) * (right - left));\n        if (heights[left] <= heights[right]) left++; else right--;\n    }\n    return best;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9345188+02:00"},{"id":"0b5de257-d362-4be5-99d1-ecf86463030f","title":"Trapping Rain Water","category":"Arrays","difficulty":"Hard","timeComplexity":"O(n)","spaceComplexity":"O(1)","tags":"array, two-pointers, prefix-maximum","pattern":"Two Pointers","summary":"Computes trapped water while maintaining the best wall seen from each side.","notes":"Process the side with the lower current maximum; that side's water is already determined.","code":"public static int TrapRainWater(int[] height)\n{\n    int left = 0, right = height.Length - 1, leftMax = 0, rightMax = 0, water = 0;\n    while (left <= right)\n    {\n        if (leftMax <= rightMax)\n        {\n            leftMax = Math.Max(leftMax, height[left]);\n            water += leftMax - height[left++];\n        }\n        else\n        {\n            rightMax = Math.Max(rightMax, height[right]);\n            water += rightMax - height[right--];\n        }\n    }\n    return water;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9345510+02:00"},{"id":"9e156f67-406b-4749-b4b3-2e6265b7f17b","title":"Product of Array Except Self","category":"Arrays","difficulty":"Medium","timeComplexity":"O(n)","spaceComplexity":"O(1) excluding output","tags":"array, prefix-product, interview","pattern":"Prefix + Suffix","summary":"Returns the product of every other element without division.","notes":"A prefix pass fills the output; a scalar suffix product completes it from right to left.","code":"public static int[] ProductExceptSelf(int[] nums)\n{\n    int[] answer = new int[nums.Length];\n    int prefix = 1;\n    for (int i = 0; i < nums.Length; i++) { answer[i] = prefix; prefix *= nums[i]; }\n    int suffix = 1;\n    for (int i = nums.Length - 1; i >= 0; i--) { answer[i] *= suffix; suffix *= nums[i]; }\n    return answer;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9345859+02:00"},{"id":"e6dd228d-acce-41ae-81d7-6ec8bb24b25d","title":"Rotate Array","category":"Arrays","difficulty":"Medium","timeComplexity":"O(n)","spaceComplexity":"O(1)","tags":"array, reversal, modular","pattern":"Three Reversals","summary":"Rotates an array right by k positions using three in-place reversals.","notes":"Normalize k by n and handle an empty array before taking the modulus.","code":"public static void RotateRight(int[] nums, int k)\n{\n    if (nums.Length == 0) return;\n    k %= nums.Length;\n    Array.Reverse(nums);\n    Array.Reverse(nums, 0, k);\n    Array.Reverse(nums, k, nums.Length - k);\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9346239+02:00"},{"id":"48a1a55a-397f-4142-bdeb-35bc35cc81a2","title":"Subarray Sum Equals K","category":"Arrays","difficulty":"Medium","timeComplexity":"O(n)","spaceComplexity":"O(n)","tags":"array, prefix-sum, hash-map","pattern":"Prefix Sum + Hash Map","summary":"Counts contiguous subarrays whose sum equals k by tracking previous prefix-sum frequencies.","notes":"Seed frequency[0] = 1 so subarrays beginning at index zero are counted.","code":"public static int CountSubarrays(int[] nums, int k)\n{\n    var frequency = new Dictionary<long, int> { [0] = 1 };\n    long prefix = 0;\n    int count = 0;\n    foreach (int value in nums)\n    {\n        prefix += value;\n        if (frequency.TryGetValue(prefix - k, out int matches)) count += matches;\n        frequency[prefix] = frequency.GetValueOrDefault(prefix) + 1;\n    }\n    return count;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9346645+02:00"},{"id":"83bfdb3c-9641-4d6d-a2d6-725c8cb430d6","title":"Longest Consecutive Sequence","category":"Arrays","difficulty":"Medium","timeComplexity":"O(n)","spaceComplexity":"O(n)","tags":"array, hash-set, sequence","pattern":"Hash Set Expansion","summary":"Finds the longest run of consecutive integers without sorting.","notes":"Only expand from values whose predecessor is absent; every sequence is scanned once.","code":"public static int LongestConsecutive(int[] nums)\n{\n    var values = nums.ToHashSet();\n    int best = 0;\n    foreach (int start in values)\n    {\n        if (values.Contains(start - 1)) continue;\n        int current = start, length = 1;\n        while (current < int.MaxValue && values.Contains(current + 1)) { current++; length++; }\n        best = Math.Max(best, length);\n    }\n    return best;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9347054+02:00"},{"id":"929d9670-4543-4352-82ad-907de6d840ac","title":"Best Time to Buy and Sell Stock","category":"Arrays","difficulty":"Easy","timeComplexity":"O(n)","spaceComplexity":"O(1)","tags":"array, greedy, stock","pattern":"Running Minimum","summary":"Finds the maximum profit from one buy followed by one later sell.","notes":"Track the cheapest earlier price and evaluate selling at the current price.","code":"public static int MaxProfit(int[] prices)\n{\n    int cheapest = int.MaxValue, best = 0;\n    foreach (int price in prices)\n    {\n        cheapest = Math.Min(cheapest, price);\n        best = Math.Max(best, price - cheapest);\n    }\n    return best;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9347457+02:00"},{"id":"acdf690d-28c1-40ad-8b23-be02eec1b728","title":"Binary Tree Inorder Traversal","category":"Trees","difficulty":"Easy","timeComplexity":"O(n)","spaceComplexity":"O(h)","tags":"tree, stack, traversal","pattern":"Iterative DFS","summary":"Visits a binary tree in left-root-right order using an explicit stack.","notes":"The iterative form avoids recursion-depth limits on highly skewed trees.","code":"public static List<int> Inorder(TreeNode? root)\n{\n    var result = new List<int>();\n    var stack = new Stack<TreeNode>();\n    while (root is not null || stack.Count > 0)\n    {\n        while (root is not null) { stack.Push(root); root = root.Left; }\n        root = stack.Pop();\n        result.Add(root.Value);\n        root = root.Right;\n    }\n    return result;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9347821+02:00"},{"id":"e7dc2d2c-302b-42ad-90c0-90cb6ae2bfa8","title":"Validate Binary Search Tree","category":"Trees","difficulty":"Medium","timeComplexity":"O(n)","spaceComplexity":"O(h)","tags":"tree, bst, recursion","pattern":"Range Constraints","summary":"Validates that every node lies strictly inside the range imposed by all of its ancestors.","notes":"Use long boundaries so int.MinValue and int.MaxValue remain valid node values.","code":"public static bool IsValidBst(TreeNode? root)\n{\n    bool Validate(TreeNode? node, long lower, long upper)\n    {\n        if (node is null) return true;\n        if (node.Value <= lower || node.Value >= upper) return false;\n        return Validate(node.Left, lower, node.Value) && Validate(node.Right, node.Value, upper);\n    }\n    return Validate(root, long.MinValue, long.MaxValue);\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9348151+02:00"},{"id":"4db7bb9b-28d6-483e-b621-d055cbd09a01","title":"Maximum Depth of Binary Tree","category":"Trees","difficulty":"Easy","timeComplexity":"O(n)","spaceComplexity":"O(h)","tags":"tree, dfs, recursion","pattern":"Tree Recursion","summary":"Returns the number of nodes on the longest path from root to leaf.","notes":"An empty tree has depth zero; a leaf has depth one.","code":"public static int MaxDepth(TreeNode? root) => root is null\n    ? 0\n    : 1 + Math.Max(MaxDepth(root.Left), MaxDepth(root.Right));","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9348490+02:00"},{"id":"8595f0a0-939a-4d9d-9741-d7731e47b425","title":"Diameter of Binary Tree","category":"Trees","difficulty":"Medium","timeComplexity":"O(n)","spaceComplexity":"O(h)","tags":"tree, dfs, diameter","pattern":"Postorder DP","summary":"Finds the maximum number of edges on a path between any two tree nodes.","notes":"Compute height and update diameter in the same postorder traversal.","code":"public static int Diameter(TreeNode? root)\n{\n    int best = 0;\n    int Height(TreeNode? node)\n    {\n        if (node is null) return 0;\n        int left = Height(node.Left), right = Height(node.Right);\n        best = Math.Max(best, left + right);\n        return 1 + Math.Max(left, right);\n    }\n    Height(root);\n    return best;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9348849+02:00"},{"id":"bd0798be-cb39-4ab4-806e-d6afc6a7d4a4","title":"Number of Islands","category":"Graphs","difficulty":"Medium","timeComplexity":"O(rows × cols)","spaceComplexity":"O(rows × cols)","tags":"graph, grid, dfs, components","pattern":"Grid Flood Fill","summary":"Counts connected components of land in a binary grid by flooding each newly discovered island.","notes":"Mark a cell before pushing its neighbors so it is never added to the stack twice.","code":"public static int CountIslands(char[][] grid)\n{\n    int islands = 0;\n    int[][] directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];\n    for (int row = 0; row < grid.Length; row++)\n        for (int col = 0; col < grid[row].Length; col++)\n        {\n            if (grid[row][col] != '1') continue;\n            islands++;\n            var stack = new Stack<(int Row, int Col)>();\n            stack.Push((row, col));\n            grid[row][col] = '0';\n            while (stack.Count > 0)\n            {\n                var (r, c) = stack.Pop();\n                foreach (var d in directions)\n                {\n                    int nr = r + d[0], nc = c + d[1];\n                    if (nr < 0 || nr >= grid.Length || nc < 0 || nc >= grid[nr].Length || grid[nr][nc] != '1') continue;\n                    grid[nr][nc] = '0';\n                    stack.Push((nr, nc));\n                }\n            }\n        }\n    return islands;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9349211+02:00"},{"id":"634d910c-640b-4b2a-9056-2f1da20c7fb3","title":"Bellman-Ford Shortest Paths","category":"Graphs","difficulty":"Hard","timeComplexity":"O(V · E)","spaceComplexity":"O(V)","tags":"graph, shortest-path, negative-weights","pattern":"Edge Relaxation","summary":"Computes single-source shortest paths even when edges can have negative weights.","notes":"A successful relaxation on the Vth pass proves a reachable negative cycle exists.","code":"public static long[] BellmanFord(int vertices, (int From, int To, int Weight)[] edges, int source)\n{\n    long infinity = long.MaxValue / 4;\n    long[] distance = Enumerable.Repeat(infinity, vertices).ToArray();\n    distance[source] = 0;\n    for (int pass = 1; pass < vertices; pass++)\n    {\n        bool changed = false;\n        foreach (var (from, to, weight) in edges)\n            if (distance[from] != infinity && distance[from] + weight < distance[to])\n            { distance[to] = distance[from] + weight; changed = true; }\n        if (!changed) break;\n    }\n    foreach (var (from, to, weight) in edges)\n        if (distance[from] != infinity && distance[from] + weight < distance[to])\n            throw new InvalidOperationException(\"Reachable negative cycle detected.\");\n    return distance;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9349552+02:00"},{"id":"f4af8cec-51d3-45cb-b7ea-53ef21b0ef51","title":"House Robber","category":"Dynamic Programming","difficulty":"Medium","timeComplexity":"O(n)","spaceComplexity":"O(1)","tags":"dp, array, rolling-state","pattern":"Take or Skip DP","summary":"Maximizes stolen value when adjacent houses cannot both be selected.","notes":"At each house, compare skipping it with taking it plus the best result two positions back.","code":"public static int Rob(int[] money)\n{\n    int twoBack = 0, oneBack = 0;\n    foreach (int value in money)\n    {\n        int current = Math.Max(oneBack, twoBack + value);\n        twoBack = oneBack;\n        oneBack = current;\n    }\n    return oneBack;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9349890+02:00"},{"id":"cefb6d55-d646-4331-a7e7-38fc7c0d34ec","title":"Climbing Stairs","category":"Dynamic Programming","difficulty":"Easy","timeComplexity":"O(n)","spaceComplexity":"O(1)","tags":"dp, fibonacci, rolling-state","pattern":"Fibonacci DP","summary":"Counts ways to reach step n when every move climbs one or two steps.","notes":"Only the previous two states are required, so the DP table can be compressed.","code":"public static int ClimbStairs(int n)\n{\n    if (n <= 1) return 1;\n    int previous = 1, current = 1;\n    for (int step = 2; step <= n; step++)\n        (previous, current) = (current, checked(previous + current));\n    return current;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9350245+02:00"},{"id":"62a9f3cf-1dd3-414a-a706-312f93aa3de9","title":"Longest Common Subsequence","category":"Dynamic Programming","difficulty":"Medium","timeComplexity":"O(n · m)","spaceComplexity":"O(m)","tags":"dp, string, subsequence","pattern":"Sequence DP","summary":"Finds the maximum-length sequence appearing in order in both strings.","notes":"Keep the previous diagonal value while updating a one-dimensional DP row.","code":"public static int LcsLength(string first, string second)\n{\n    int[] dp = new int[second.Length + 1];\n    foreach (char a in first)\n    {\n        int diagonal = 0;\n        for (int j = 1; j <= second.Length; j++)\n        {\n            int old = dp[j];\n            dp[j] = a == second[j - 1] ? diagonal + 1 : Math.Max(dp[j], dp[j - 1]);\n            diagonal = old;\n        }\n    }\n    return dp[^1];\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9350588+02:00"},{"id":"36b0fa80-dc06-48bb-a7f4-f86b69395a63","title":"Edit Distance","category":"Dynamic Programming","difficulty":"Hard","timeComplexity":"O(n · m)","spaceComplexity":"O(m)","tags":"dp, string, levenshtein","pattern":"String Transformation DP","summary":"Finds the minimum insertions, deletions, and replacements required to transform one string into another.","notes":"Each state considers the cheapest predecessor operation; equal characters copy the diagonal state.","code":"public static int EditDistance(string source, string target)\n{\n    int[] dp = Enumerable.Range(0, target.Length + 1).ToArray();\n    for (int i = 1; i <= source.Length; i++)\n    {\n        int diagonal = dp[0];\n        dp[0] = i;\n        for (int j = 1; j <= target.Length; j++)\n        {\n            int old = dp[j];\n            dp[j] = source[i - 1] == target[j - 1]\n                ? diagonal\n                : 1 + Math.Min(diagonal, Math.Min(dp[j], dp[j - 1]));\n            diagonal = old;\n        }\n    }\n    return dp[^1];\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9351011+02:00"},{"id":"e31b1a7f-fd46-4d7b-b2c0-d5b1cd79bf18","title":"Generate Subsets","category":"Backtracking","difficulty":"Medium","timeComplexity":"O(n · 2ⁿ)","spaceComplexity":"O(n) recursion","tags":"backtracking, subsets, recursion","pattern":"Include or Exclude","summary":"Generates the power set by deciding whether to include every input value.","notes":"Clone the current path when recording it because the same list is mutated during backtracking.","code":"public static List<List<int>> Subsets(int[] nums)\n{\n    var result = new List<List<int>>();\n    var current = new List<int>();\n    void Search(int index)\n    {\n        if (index == nums.Length) { result.Add([.. current]); return; }\n        Search(index + 1);\n        current.Add(nums[index]);\n        Search(index + 1);\n        current.RemoveAt(current.Count - 1);\n    }\n    Search(0);\n    return result;\n}","favorite":false,"masteryLevel":"New","reviewCount":0,"updatedAt":"2026-09-02T01:55:01.9351432+02:00"}];
